function t(){return{tasks:[{text:"На какой ключевой идее строится алгоритм kNN?",type:"choice",answer:"Похожие по признакам объекты обычно имеют похожие значения целевой переменной",options:["Похожие по признакам объекты обычно имеют похожие значения целевой переменной","Все объекты в выборке равнозначны и никак не связаны друг с другом","Таргет всегда линейно зависит от признаков","Чем больше признаков, тем точнее предсказание"],hint:"Отсюда и стратегия — искать соседей по признакам",difficulty:"Легко"},{text:"Как kNN формирует предсказание для задачи регрессии?",type:"choice",answer:"Усредняет таргеты k ближайших соседей",options:["Усредняет таргеты k ближайших соседей","Голосованием выбирает самый частый класс среди соседей","Строит формулу с коэффициентами по всей выборке","Берёт таргет только одного, самого первого объекта выборки"],hint:"Для классификации используется другой способ — голосование",difficulty:"Легко"},{text:"Что делает kNN при классификации, если голоса соседей разделились поровну?",type:"choice",answer:"Берёт класс самого ближайшего из спорных соседей",options:["Берёт класс самого ближайшего из спорных соседей","Всегда возвращает ошибку и не даёт предсказания","Выбирает класс случайным образом без учёта расстояния","Увеличивает k в два раза и повторяет голосование"],hint:"Простое правило-тайбрейкер при равенстве голосов",difficulty:"Средне"},{text:"Какой первый шаг общего алгоритма kNN?",type:"choice",answer:"В алгоритм поступает новый объект, для которого нужно сделать предсказание",options:["В алгоритм поступает новый объект, для которого нужно сделать предсказание","Сразу выбираются k ближайших соседей без расчёта расстояний","Обучается набор коэффициентов β","Данные делятся на train и test"],hint:"Дальше считаются попарные расстояния до всех объектов обучения",difficulty:"Легко"},{text:"Чем принципиально отличаются линейные модели от kNN?",type:"choice",answer:"Линейные модели параметрические (обучают коэффициенты заранее), а kNN — непараметрический, смотрит на соседей каждый раз заново",options:["Линейные модели параметрические (обучают коэффициенты заранее), а kNN — непараметрический, смотрит на соседей каждый раз заново","kNN всегда работает быстрее линейных моделей на больших данных","Линейные модели вообще не поддаются интерпретации","kNN умеет экстраполировать тренд лучше линейных моделей"],hint:"У линейных моделей есть готовые коэффициенты β, у kNN — нет",difficulty:"Средне"},{text:"Почему kNN работает медленно на больших датасетах?",type:"choice",answer:"Для каждого нового объекта нужно считать расстояние до всех объектов обучающей выборки",options:["Для каждого нового объекта нужно считать расстояние до всех объектов обучающей выборки","Потому что алгоритм требует ежедневного переобучения коэффициентов","Потому что kNN всегда работает только с текстовыми данными","Потому что kNN не поддерживает параллельные вычисления в принципе"],hint:"В отличие от параметрических моделей, у kNN нет заранее готовой формулы",difficulty:"Средне"},{text:"При каком значении параметра p расстояние Минковского превращается в евклидово?",type:"choice",answer:"p = 2",options:["p = 2","p = 1","p = 0","p = бесконечность"],hint:"При p = 1 получается манхэттенское расстояние",difficulty:"Средне"},{text:"Как параметр p влияет на вклад разницы между объектами при p больше 1?",type:"choice",answer:"С ростом разницы по признаку её вклад в расстояние увеличивается",options:["С ростом разницы по признаку её вклад в расстояние увеличивается","С ростом разницы по признаку её вклад в расстояние уменьшается","Параметр p при p > 1 никак не влияет на расстояние","Параметр p обнуляет вклад всех признаков сразу"],hint:"При p < 1 эффект обратный — вклад крупных различий уменьшается",difficulty:"Сложно"},{text:"Зачем нужно перевзвешивание соседей (например, через гауссовское ядро)?",type:"choice",answer:"Чтобы более близкие соседи вносили больший вклад в предсказание, чем дальние",options:["Чтобы более близкие соседи вносили больший вклад в предсказание, чем дальние","Чтобы ускорить расчёт расстояний между объектами","Чтобы автоматически подобрать оптимальное k","Чтобы заменить масштабирование признаков"],hint:"Без перевзвешивания все k соседей учитываются одинаково",difficulty:"Средне"},{text:"Зачем перед запуском kNN нужно масштабировать признаки (например, через StandardScaler)?",type:"choice",answer:"Иначе признак с большим числовым диапазоном будет доминировать в расстоянии просто из-за масштаба, а не значимости",options:["Иначе признак с большим числовым диапазоном будет доминировать в расстоянии просто из-за масштаба, а не значимости","Масштабирование ускоряет обучение линейных моделей, а не kNN","Без масштабирования kNN вообще не запустится и выдаст ошибку","Масштабирование нужно только для задач классификации, но не регрессии"],hint:"StandardScaler приводит признаки к среднему 0 и стандартному отклонению 1",difficulty:"Средне"}]}}export{t as default};
